shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ece6d9;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c8c0af;
    --accent: #b85d19;
    --accent-red: #9e2a2b;
    --accent-soft: rgba(184, 93, 25, 0.12);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-line: #283f56;
    --font-serif-en: 'Playfair Display', Georgia, serif;
    --font-body-en: 'Lora', Georgia, serif;
    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans-cn: 'Noto Sans SC', -apple-system, sans-serif;
    --font-sans-en: 'Inter', -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  /* Strictly enforce language toggle visibility */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    font-family: var(--font-body-en), var(--font-serif-cn);
    background-color: var(--paper);
    color: var(--body);
    line-height: 1.8;
    overflow-x: hidden;
  }

  :host([lang="zh-CN"]) .wsj-shadow-body {
    font-family: var(--font-serif-cn), serif;
    line-height: 1.9;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-body-en), serif;
    line-height: 1.78;
  }

  /* Progress Bar */
  .progress-bar {
    position: fixed;
    top: 0;
    left: 0;
    height: 3px;
    background: var(--accent);
    width: 0%;
    z-index: 1001;
    transition: width 0.1s ease-out;
  }

  /* Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0.75rem 1.5rem;
  }

  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-group {
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
  }

  .wsj-logo {
    font-family: var(--font-serif-en);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.04em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .edition-badge {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-left: 1px solid var(--line-strong);
    padding-left: 0.75rem;
  }

  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 999px;
    padding: 2px;
  }

  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-sans-en), var(--font-sans-cn);
    font-size: 0.76rem;
    font-weight: 600;
    padding: 0.28rem 0.75rem;
    border-radius: 999px;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.2s ease;
  }

  :host([lang="zh-CN"]) .lang-btn[data-lang="zh-CN"],
  :host([lang="en"]) .lang-btn[data-lang="en"] {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .hero {
    max-width: 1180px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 1px solid var(--line);
  }

  .hero-kicker {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--accent);
  }

  .hero-kicker .dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--accent-red);
    display: inline-block;
  }

  .article-title {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-weight: 800;
    font-size: clamp(2rem, 4.2vw, 3.35rem);
    line-height: 1.18;
    color: var(--ink);
    max-width: 960px;
    margin-bottom: 1.25rem;
    letter-spacing: -0.015em;
  }

  :host([lang="zh-CN"]) .article-title {
    font-family: var(--font-serif-cn);
    font-weight: 700;
    line-height: 1.26;
    letter-spacing: 0;
  }

  .article-dek {
    font-size: clamp(1.1rem, 1.8vw, 1.35rem);
    line-height: 1.6;
    color: var(--muted);
    max-width: 820px;
    margin-bottom: 2rem;
    font-weight: 400;
  }

  .meta-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans-en), var(--font-sans-cn);
    font-size: 0.82rem;
    color: var(--muted);
  }

  .byline strong {
    color: var(--ink);
    font-weight: 600;
    letter-spacing: 0.03em;
  }

  /* Situation Strip inside Hero */
  .situation-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1px;
    background: var(--line-strong);
    border: 1px solid var(--line-strong);
    margin-top: 2rem;
  }

  .sit-cell {
    background: var(--paper-card);
    padding: 1rem 1.15rem;
  }

  .sit-tag {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--muted);
    margin-bottom: 0.35rem;
  }

  .sit-val {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.2;
    margin-bottom: 0.25rem;
  }

  .sit-val.alert {
    color: var(--accent-red);
  }

  .sit-desc {
    font-family: var(--font-sans-en), var(--font-sans-cn);
    font-size: 0.76rem;
    color: var(--muted);
    line-height: 1.4;
  }

  /* Main Container & Editorial Grid */
  .editorial-container {
    max-width: 1180px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 5rem;
  }

  .editorial-grid {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(260px, 360px);
    justify-content: space-between;
    gap: 3.5rem;
    align-items: start;
  }

  .prose-stream {
    width: 100%;
  }

  .rail-stream {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
  }

  /* Prose Styling */
  .prose-p {
    font-size: 1.125rem;
    margin-bottom: 1.45rem;
    color: var(--body);
  }

  .lead-p {
    font-size: 1.24rem;
    line-height: 1.85;
    color: var(--ink);
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.75rem;
  }

  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
    color: inherit;
    padding: 0 2px;
    font-weight: 600;
  }

  /* Chapter Dividers */
  .chapter-divider {
    margin: 3.25rem 0 2rem;
    padding-top: 1.75rem;
    border-top: 2px solid var(--ink);
  }

  .chapter-num {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--accent);
    margin-bottom: 0.35rem;
    display: block;
  }

  .chapter-heading {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-size: 1.55rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.3;
  }

  /* Incident Forensic Box (p3, p4, p5) */
  .forensic-dossier {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-left: 4px solid var(--accent-red);
    padding: 1.5rem 1.65rem;
    margin: 1.75rem 0 2rem;
  }

  .dossier-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid var(--line-strong);
    padding-bottom: 0.65rem;
    margin-bottom: 1.15rem;
    font-family: var(--font-mono);
    font-size: 0.74rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent-red);
    font-weight: 700;
  }

  .forensic-dossier .prose-p:last-child {
    margin-bottom: 0;
  }

  /* Split Sentence Verdict / Analytical Callout */
  .verdict-quote {
    margin: 1.5rem 0 2rem;
    padding: 1.35rem 1.5rem;
    background: var(--navy-bg);
    color: var(--paper);
    border-left: 4px solid var(--accent);
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-size: 1.22rem;
    line-height: 1.65;
  }

  /* Derived Pull Quote & Metric Cards in Rail */
  .rail-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.35rem;
  }

  .rail-card-title {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--accent);
    padding-bottom: 0.6rem;
    margin-bottom: 0.9rem;
    border-bottom: 1px solid var(--line-strong);
    font-weight: 600;
  }

  .pull-quote {
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 1px solid var(--line-strong);
    padding: 1.35rem 0;
  }

  .pull-quote .quote-text {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-size: 1.15rem;
    font-weight: 600;
    color: var(--ink);
    line-height: 1.55;
    margin-bottom: 0.65rem;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-sans-en), var(--font-sans-cn);
    font-size: 0.78rem;
    color: var(--muted);
  }

  .metric-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--accent);
    padding: 1.25rem 1.35rem;
  }

  .metric-val {
    font-family: var(--font-mono);
    font-size: 2rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.1;
    margin-bottom: 0.45rem;
  }

  .metric-lbl {
    font-family: var(--font-sans-en), var(--font-sans-cn);
    font-size: 0.84rem;
    font-weight: 600;
    color: var(--body);
    margin-bottom: 0.4rem;
    line-height: 1.45;
  }

  .metric-note {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--muted);
  }

  /* Bespoke SVG Figure Cards */
  .figure-panel {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.5rem;
    margin: 2.25rem 0;
  }

  .figure-panel.dark-panel {
    background: var(--navy-bg);
    border-color: var(--navy-line);
    color: var(--paper);
  }

  .fig-kicker {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 0.3rem;
  }

  .fig-title {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 0.35rem;
    line-height: 1.35;
  }

  .fig-sub {
    font-family: var(--font-sans-en), var(--font-sans-cn);
    font-size: 0.82rem;
    color: var(--muted);
    margin-bottom: 1.15rem;
    line-height: 1.5;
  }

  .dark-panel .fig-sub {
    color: #a9b8c9;
  }

  .fig-footnote {
    font-family: var(--font-sans-en), var(--font-sans-cn);
    font-size: 0.74rem;
    color: var(--muted);
    margin-top: 0.85rem;
    padding-top: 0.65rem;
    border-top: 1px solid var(--line-strong);
  }

  .dark-panel .fig-footnote {
    color: #8fa3b8;
    border-top-color: var(--navy-line);
  }

  /* Timeline Dossier List */
  .timeline-list {
    list-style: none;
    position: relative;
    padding-left: 1rem;
    border-left: 2px solid var(--line-strong);
  }

  .timeline-item {
    position: relative;
    margin-bottom: 1.1rem;
    padding-left: 0.65rem;
  }

  .timeline-item:last-child {
    margin-bottom: 0;
  }

  .timeline-item::before {
    content: '';
    position: absolute;
    left: -1.38rem;
    top: 0.38rem;
    width: 9px;
    height: 9px;
    border-radius: 50%;
    background: var(--accent);
    border: 2px solid var(--paper-card);
  }

  .tl-date {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--accent);
    display: block;
    margin-bottom: 0.15rem;
  }

  .tl-text {
    font-family: var(--font-sans-en), var(--font-sans-cn);
    font-size: 0.82rem;
    line-height: 1.48;
    color: var(--body);
  }

  /* Context Footer Dossier */
  .context-footer {
    margin-top: 3.5rem;
    background: var(--paper-deep);
    border: 1px solid var(--line-strong);
    padding: 1.75rem 2rem;
  }

  .context-label {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 0.65rem;
    font-weight: 700;
  }

  .context-body {
    font-family: var(--font-sans-en), var(--font-sans-cn);
    font-size: 0.92rem;
    line-height: 1.75;
    color: var(--body);
  }

  /* Responsive Design */
  @media (max-width: 960px) {
    .editorial-grid {
      grid-template-columns: 1fr;
      gap: 2.25rem;
    }
    .situation-strip {
      grid-template-columns: repeat(2, 1fr);
    }
  }

  @media (max-width: 560px) {
    .masthead {
      padding: 0.65rem 1rem;
    }
    .hero {
      padding: 2.25rem 1rem 1.75rem;
    }
    .editorial-container {
      padding: 1.75rem 1rem 3.5rem;
    }
    .situation-strip {
      grid-template-columns: 1fr;
    }
    .prose-p {
      font-size: 1.05rem;
    }
    .lead-p {
      font-size: 1.12rem;
    }
    .figure-panel {
      padding: 1.1rem;
    }
    .context-footer {
      padding: 1.25rem;
    }
  }
